use vstd::prelude::*;

verus! {
    /// Insert `value` into vector `arr` at position `idx`,
    /// shifting all elements at `idx..` one position to the right.
    fn numpy_insert<T: Clone + PartialEq>(
        arr: Vec<T>, 
        idx: usize, 
        value: T
    ) -> (res: Vec<T>)
        requires
            // insertion index is valid: 0 ≤ idx ≤ arr.len()
            idx <= arr.len(),
        ensures
            // result length is exactly one more than original
            res.len() == arr.len() + 1,
        ensures
            // all elements before idx are unchanged
            forall |j: usize| j < idx ==> res[j] == arr[j],
        ensures
            // the new value appears at position idx
            res[idx] == value,
        ensures
            // all elements from idx..arr.len() have been shifted right by one
            forall |j: usize| idx <= j && j < arr.len() ==>
                res[j + 1] == arr[j],
    {
        // We'll build a fresh vector `res` of capacity arr.len() + 1
        let mut res = Vec::new();
        res.reserve(arr.len() + 1);

        // 1) Copy the prefix arr[0..idx] into res[0..idx]
        let mut i: usize = 0;
        while i < idx
            invariant
                i <= idx,
                // we've pushed exactly i elements so far
                res.len() == i,
                // those i elements match arr[0..i]
                forall |j: usize| j < i ==> res[j] == arr[j],
            decreases idx - i
        {
            res.push(arr[i].clone());
            i += 1;
        }
        // now i == idx, res.len() == idx, and prefix invariant holds

        // 2) Push the new value at position idx
        res.push(value);

        // 3) Copy the suffix arr[idx..arr.len()] into res[idx+1..]
        let mut k: usize = idx;
        while k < arr.len()
            invariant
                k <= arr.len(),
                // we've pushed exactly idx+1 + (k-idx) elements so far
                res.len() == idx + 1 + (k - idx),
                // prefix still intact
                forall |j: usize| j < idx ==> res[j] == arr[j],
                // the inserted value is at res[idx]
                res[idx] == value,
                // for all j in [idx..k), res[j+1] == arr[j]
                forall |j: usize| idx <= j && j < k ==> res[j+1] == arr[j],
            decreases arr.len() - k
        {
            res.push(arr[k].clone());
            k += 1;
        }
        // now k == arr.len(), res.len() == arr.len() + 1

        res
    }
}

